local INFO_WHITE, INFO_RELOAD, INFO_SPAWN, INFO_SHIELD = Color3.fromRGB(235, 228, 210), Color3.fromRGB(255, 150, 40), Color3.fromRGB(120, 220, 255), Color3.fromRGB(255, 205, 70)
local function infoFor(plr, char)
    local c = espInfo[plr]
    if c and tick() - c.at < 0.2 then return c.text, c.col end
    local text, col = "", INFO_WHITE
    pcall(function()
        local f = FighterController and FighterController:GetFighter(char)
        if not f then return end
        local inv = false
        pcall(function() inv = f.Entity and f.Entity:Get("IsInvincible") == true end)
        if inv or char:FindFirstChildOfClass("ForceField") then text, col = "SPAWN SHIELD", INFO_SPAWN return end
        local it = f.EquippedItem
        if not it then return end
        local name = tostring(it.Name)
        local ammo
        pcall(function() ammo = it:Get("Ammo") end)
        if name == "Riot Shield" and type(ammo) == "number" then
            text, col = ("Riot Shield · %d HP"):format(ammo), INFO_SHIELD
        elseif tick() < (rawget(it, "_reload_cooldown") or it._reload_cooldown or 0) then
            text, col = name .. " · RELOADING", INFO_RELOAD
        elseif type(ammo) == "number" and it.Info and type(it.Info.MaxAmmo) == "number" then
            text = ("%s · %d/%d"):format(name, ammo, it.Info.MaxAmmo)
        else
            text = name
        end
    end)
    espInfo[plr] = { at = tick(), text = text, col = col }
    return text, col
end
local function hideESP(e) for _, d in pairs(e) do d.Visible = false end end
C._conns.esp = RS.RenderStepped:Connect(function()
