        return
    end
    for _, plr in ipairs(Players:GetPlayers()) do
        local e = esp[plr]
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if C.ESPOn and isEnemy(plr) and hrp then
            local head = char:FindFirstChild("Head") or hrp
            local hum = char:FindFirstChildOfClass("Humanoid")
            local rootPos, onScreen = cam:WorldToViewportPoint(hrp.Position)
            local dist = (cam.CFrame.Position - hrp.Position).Magnitude
            if onScreen and dist <= C.ESPMax then
                if not e then e = makeESP(); esp[plr] = e end
                local headPos = cam:WorldToViewportPoint(head.Position + Vector3.new(0, 0.5, 0))
                local legPos  = cam:WorldToViewportPoint(hrp.Position - Vector3.new(0, 3, 0))
                local h = math.abs(headPos.Y - legPos.Y)
                local w = h / 2
                local x = headPos.X - w / 2
                local col = C.EnemyColor
                e.box.Visible = C.ESPBox; e.box.Color = col; e.box.Position = Vector2.new(x, headPos.Y); e.box.Size = Vector2.new(w, h)
                e.name.Visible = C.ESPName; e.name.Color = col; e.name.Text = plr.DisplayName; e.name.Position = Vector2.new(headPos.X, headPos.Y - 16)
                e.dist.Visible = C.ESPDistance; e.dist.Color = col; e.dist.Text = math.floor(dist) .. "m"; e.dist.Position = Vector2.new(legPos.X, legPos.Y + 2)
                if C.ESPWeapon then
                    local itxt, icol = infoFor(plr, char)
                    e.info.Visible = itxt ~= ""; e.info.Text = itxt; e.info.Color = icol
                    e.info.Position = Vector2.new(legPos.X, legPos.Y + (C.ESPDistance and 16 or 2))
                else e.info.Visible = false end
                if C.ESPHealth and hum then
                    local frac = math.clamp(hum.Health / (hum.MaxHealth > 0 and hum.MaxHealth or 100), 0, 1)
                    local bx = x - 4
                    e.hpbg.Visible = true; e.hpbg.From = Vector2.new(bx, headPos.Y); e.hpbg.To = Vector2.new(bx, legPos.Y); e.hpbg.Color = Color3.new(0, 0, 0)
                    e.hp.Visible = true; e.hp.From = Vector2.new(bx, legPos.Y); e.hp.To = Vector2.new(bx, legPos.Y - h * frac); e.hp.Color = Color3.fromRGB(255 * (1 - frac), 255 * frac, 0)
                else e.hpbg.Visible = false; e.hp.Visible = false end
                if C.ESPTracer then
                    e.tracer.Visible = true; e.tracer.Color = col
