                else e.tracer.Visible = false end
            elseif e then hideESP(e) end
        elseif e then hideESP(e) end
    end
    for p, e in pairs(esp) do
        if not p.Parent then for _, d in pairs(e) do pcall(function() d:Remove() end) end esp[p] = nil end
    end
end)
