local function rewrite(lf, data)
    if not W.On then return data end
    if type(data) ~= "table" or type(data[K[0]]) ~= "table" or type(data[K[1]]) ~= "table" then return data end
    local hb, model = W.target, W.tmodel
    if not (hb and hb:IsDescendantOf(workspace)) then return data end
    local okO, origin = pcall(decode, data[K[0]])
    if not okO then return data end
    local head = origin.Position
    local list = mapList()
    local tp, tpred = predicted(hb, model)
    local oPos
    if sees(head, tp, tpred, model, list) then
        oPos = head
    else
        local len = (tp - head).Magnitude
        local cap = math.max(0, math.min(W.Studs or SHIFT_MAX, len - 2))
        local need = needShift(head, tp, model, list)
        if need <= cap then
            local L = (tp - head).Unit
