local function candidates()
    local list = gameTargets()
    R.src = list and "game" or "attr"
    list = list or attrTargets()
    local lf = FC.LocalFighter
    local myTeam = teamOf(lf, player)
    local out = {}
    for _, m in ipairs(list) do
        local plr = Players:GetPlayerFromCharacter(m)
        local f = fighterOf(m)
        local isPlayer = plr ~= nil or (f ~= nil and f ~= lf and Players:FindFirstChild(m.Name) ~= nil)
        plr = plr or (isPlayer and Players:FindFirstChild(m.Name)) or nil
        local ok = true
        if not isPlayer and not R.Dummies then ok = false end
        if ok and plr and R.ignore[plr.Name] then ok = false end
        if ok and R.SkipTeam and isPlayer then
            local t = teamOf(f, plr)
            if myTeam ~= nil and t ~= nil and t == myTeam then ok = false end
        end
        if ok and R.KatanaMode == "Skip" and deflecting(m) then ok = false end
        if ok and R.SkipFF and invincible(m) then ok = false end
        if ok and R.skip[m] and tick() < R.skip[m] then ok = false end
        if ok then out[#out + 1] = m end
    end
    return out
end
local function pick(fromPos)
    local best, score
    for _, m in ipairs(candidates()) do
        local s
        local hp = humOf(m).Health
        local dist = (m.HumanoidRootPart.Position - fromPos).Magnitude
        if R.Mode == "Lowest HP" then
            s = hp
        elseif R.Mode == "Nearest" then
            s = dist
        else
            s = dist / 40 + hp / 50
            if R.shieldRaw and R.shieldRaw(m) then s = s + 1.5 end
            if deflecting(m) then s = s + 2 end
            if R.lastAttacker == m and tick() - (R.lastHurtAt or 0) < 4 then s = s - 2 end
            local fails = R.fails[m]
            if fails then s = s + math.min(fails, 4) * 0.75 end
        end
        if not score or s < score then best, score = m, s end
    end
    return best
end
local function gunOf(lf)
