local function rewrite(data)
    local m = R.target
    if not (m and type(data) == "table" and type(data[K[0]]) == "table" and type(data[K[1]]) == "table") then return data end
    local hb = headOf(m)
    if not hb then return data end
    local okO, origin = pcall(decode, data[K[0]])
    local okA, aim = pcall(decode, data[K[1]])
    if not (okO and okA) then return data end
    local oPos = origin.Position
    local _, hrp = myParts()
    if hrp and (oPos - hrp.Position).Magnitude > 12 then oPos = hrp.Position + Vector3.new(0, 1.5, 0) end
    local tpos = aimPoint(m) or hb.Position
    if (tpos - oPos).Magnitude < 0.2 then oPos = oPos + Vector3.new(0, 0.5, 0) end
    local aPos = aim.Position + (oPos - origin.Position)
    local out = {}
    for k, v in pairs(data) do out[k] = v end
    out[K[0]] = encode(CFrame.lookAt(oPos, tpos))
    out[K[1]] = encode(CFrame.lookAt(aPos, tpos))
    out[K[2]] = hb
    out[K[3]] = encode(hb.CFrame:ToObjectSpace(CFrame.lookAt(tpos, tpos + (oPos - tpos).Unit)))
    R.shots = R.shots + 1
    if R.shots <= 3 or R.shots % 10 == 0 then
        log(("SHOT #%d at %s dist %.1f"):format(R.shots, m.Name, (tpos - oPos).Magnitude))
    end
    return out
end
local function uninstall()
    local lf = R.hookedLF
    if lf then
        if not pcall(rawset, lf, "GetCameraData", nil) then
            pcall(function() lf.GetCameraData = R.origGCD end)
        end
    end
    R.hookedLF, R.origGCD = nil, nil
end
R.Rewrite = function(self, data)
    if not (R.On and R.target and gunOf(self)) then return nil end
    R.lastShot = tick()
    R.firedAt = R.firedAt or tick()
    local out = rewrite(data)
    if out == data then return nil end
    return out
end
local function install(lf)
    local orig = lf.GetCameraData
    if type(orig) ~= "function" then return end
    R.hookedLF, R.origGCD = lf, orig
    lf.GetCameraData = function(self, ...)
        local res = table.pack(orig(self, ...))
        if select("#", ...) == 0 and self == R.hookedLF then
            local ok, out = pcall(R.Rewrite, self, res[1])
            if ok and out then res[1] = out end
        end
        return table.unpack(res, 1, res.n)
    end
end
