            local t = mine:GetAttribute("TeamID")
            if not (myTeam ~= nil and t ~= nil and t == myTeam) then
                local hb = mine:FindFirstChild("Hitbox")
                if hb and not hb:IsA("BasePart") then hb = hb:FindFirstChildWhichIsA("BasePart", true) end
                if hb then out[#out + 1] = hb end
            end
        end
    end
