    local side
    pcall(function()
        local eq = f.EquippedItem
        for _, it in pairs(f.Items or {}) do
            if type(it) == "table" and (it.Name == "Riot Shield" or (type(it.Info) == "table" and it.Info.AmmoType == "Shield")) then
                local ammo = 1
                pcall(function() ammo = it:Get("Ammo") end)
                if not (type(ammo) == "number" and ammo <= 0) then
                    side = (it == eq) and "front" or "back"
                end
            end
        end
    end)
    return side
end
