local function spotOK(pos, ignore)
    spotParams.FilterDescendantsInstances = ignore
    local ok, parts = pcall(function() return workspace:GetPartBoundsInBox(CFrame.new(pos), Vector3.new(2.5, 5, 2.5), spotParams) end)
    if ok then
        for _, p in ipairs(parts) do
            if p.Anchored then
                if badName(p) then return false, "barrier " .. p.Name end
                if p.CanCollide and p.Transparency < 1 then return false, "wall " .. p.Name end
            end
        end
    end
    downParams.FilterDescendantsInstances = ignore
    local hit = workspace:Raycast(pos, Vector3.new(0, -120, 0), downParams)
    if not hit then return false, "no floor" end
    if hit.Instance.Anchored and killName(hit.Instance) then return false, "kill floor " .. hit.Instance.Name end
    return true
end
local function spots(thrp, head, side)
    local list = {}
    local look = thrp.CFrame.LookVector * Vector3.new(1, 0, 1)
    look = look.Magnitude > 0.01 and look.Unit or Vector3.zAxis
    local dir = side == "behind" and -look or side == "front" and look or nil
    if dir then
        for _, h in ipairs({ 0, 3, 6 }) do list[#list + 1] = head + dir * 3.5 + Vector3.new(0, 2 + h, 0) end
    else
        for _, h in ipairs({ 0, 2, 4, 7, 10, 14, 18 }) do list[#list + 1] = head + Vector3.new(0, 2 + h, 0) end
    end
    for _, r in ipairs({ 4, 7, 11 }) do
        for k = 0, 7 do
            local a = k * math.pi / 4
            local d = Vector3.new(math.cos(a), 0, math.sin(a))
            if not dir or d:Dot(dir) > 0.2 then
                list[#list + 1] = head + d * r + Vector3.new(0, 3.5, 0)
            end
        end
    end
    return list
end
local function approachSide(m)
    local blockFront = R.KatanaMode == "Go behind" and deflecting(m)
    local shield = shieldSide(m)
    if shield == "front" then blockFront = true end
    local blockBack = shield == "back"
    if shield and R.shieldLogFor ~= m then
        R.shieldLogFor = m
        log(("SHIELD %s on %s"):format(m.Name, shield))
    end
    if blockFront and blockBack then return nil end
    if blockFront then return "behind" end
    if blockBack then return "front" end
    return nil
end
local function placeCF(m, mines, hrp)
    local thrp = m:FindFirstChild("HumanoidRootPart")
    local aimAt = aimPoint(m)
    if not (thrp and aimAt) then return nil end
    local _, yaw = hrp.CFrame:ToEulerAnglesYXZ()
    local function finish(pos)
        local flat = (aimAt - pos) * Vector3.new(1, 0, 1)
        if flat.Magnitude > 0.5 then yaw = math.atan2(-flat.X, -flat.Z) end
        return CFrame.new(pos) * CFrame.Angles(0, yaw, 0)
    end
    if R.MeleeStandoff ~= false then
        local info
        pcall(function() local f = fighterOf(m) info = f and f.EquippedItem and f.EquippedItem.Info end)
        if type(info) == "table" and (info.Class == "Melee" or info.Type == "Melee") then
            local reach = math.max(tonumber(info.AttackReach) or 6, tonumber(info.HeavyAttackReach) or 0)
            local d = reach + 3
            local anchor = m:FindFirstChild("UpperTorso") or m:FindFirstChild("Torso") or thrp
            local cf = anchor.CFrame * CFrame.new(0, 1.5, d)
            if #mines == 0 or safeAt(cf.Position, mines) then
                R.spotCache = { m = m, follow = d, up = 1.5, at = tick() }
                return cf
            end
        end
    end
    local side = approachSide(m)
    local mode = (R.Method == "Behind (bang)") and (side == "front" and "front" or "behind") or side
    if mode == "behind" or mode == "front" then
        local d = (mode == "behind" and 1 or -1) * (R.BehindDist or 1.1)
        local anchor = m:FindFirstChild("UpperTorso") or m:FindFirstChild("Torso") or thrp
        local cf = anchor.CFrame * CFrame.new(0, 0, d)
        if #mines == 0 or safeAt(cf.Position, mines) then
            R.spotCache = { m = m, follow = d, at = tick() }
            return cf
        end
    end
    local inside = thrp.Position + Vector3.new(0, R.Height, 0)
    if not side and (#mines == 0 or safeAt(inside, mines)) then
        R.spotCache = { m = m, off = inside - aimAt, at = tick(), inside = true }
        return finish(inside)
    end
    local c = R.spotCache
    if c and c.m == m and not c.inside and c.off and tick() - c.at < 0.15 then
        return finish(aimAt + c.off)
    end
    local list = spots(thrp, aimAt, side)
    if side then
        for _, h in ipairs({ 0, 2, 4, 7, 10 }) do list[#list + 1] = aimAt + Vector3.new(0, 2 + h, 0) end
        if #mines == 0 or safeAt(inside, mines) then
            R.spotCache = { m = m, off = inside - aimAt, at = tick(), inside = true }
            local ignoreSide = charList()
            for _, pos in ipairs(list) do
                if spotOK(pos, ignoreSide) and clearShot(pos + Vector3.new(0, 1.5, 0), m, aimAt, ignoreSide) then
                    R.spotCache = { m = m, off = pos - aimAt, at = tick() }
                    return finish(pos)
                end
            end
            return finish(inside)
        end
    end
    local ignore = charList()
    local why = {}
    for i, pos in ipairs(list) do
        local straight = ((pos - aimAt) * Vector3.new(1, 0, 1)).Magnitude < 0.5
        local good, reason = true, nil
        if #mines > 0 and not safeAt(pos, mines) then good, reason = false, "mine" end
        if good then good, reason = spotOK(pos, ignore) end
        if good and not straight then good, reason = clearShot(pos + Vector3.new(0, 1.5, 0), m, aimAt, ignore) end
        if not good and #why < 6 then why[#why + 1] = ("%d:%s"):format(i, tostring(reason)) end
        if good then
            if i > 1 and R.avoidLogFor ~= m then
                R.avoidLogFor = m
                log(("MOVED %s spot %d (%s) because %s"):format(m.Name, i, straight and "above" or "side", table.concat(why, ", ")))
            end
            R.spotCache = { m = m, off = pos - aimAt, at = tick() }
            return finish(pos)
        end
    end
    if R.blockLogFor ~= m then
        R.blockLogFor = m
        log(("NOSPOT %s: %s"):format(m.Name, table.concat(why, ", ")))
    end
    return nil, (#mines > 0) and "mine" or "blocked"
end
local function parkCF()
    local base = R.startCF and R.startCF.Position or Vector3.zero
    return CFrame.new(base + Vector3.new(R.HideDist, 40, R.HideDist))
end
local function releaseCamera()
    if CC then pcall(function() CC.Rotation = Vector2.new(0, CC.Rotation.Y) end) end
end
local function setTarget(m)
    R.target = m
    R.landAt, R.lastDmgAt = tick(), 0
    R.fireReadyAt = tick() + 0.03
    pcall(function()
        local mine = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        local theirs = m and m:FindFirstChild("HumanoidRootPart")
        if mine and theirs and (mine.Position - theirs.Position).Magnitude > 25 then
            R.fireReadyAt = tick() + (R.TPSettle or 0.2)
        end
    end)
    R.firedAt, R.nextReq = nil, false
    local hum = humOf(m)
    R.lastHP = hum and hum.Health or nil
    if m then
        local thrp = m:FindFirstChild("HumanoidRootPart")
        log(("TARGET %s (%s, hp %s, src %s)"):format(m.Name, Players:GetPlayerFromCharacter(m) and "player" or "npc",
            tostring(R.lastHP and math.floor(R.lastHP)), R.src))
        if not thrp then log("ERR target has no root") end
    end
end
local function stopRage()
    local _, hrp = myParts()
    if hrp and R.wasOn and R.ReturnOnStop and R.startCF and inMatch() then
        local back = R.startCF
        if not safeAt(back.Position, enemyMines()) then back = back + Vector3.new(0, 10, 0) end
        pcall(hold, hrp, back)
    end
    if R.wasOn then
        log(("STOP kills %d shots %d hits %d"):format(R.kills, R.shots, R.hits))
        flushLog()
    end
    releaseCamera()
    R.target, R.wasOn = nil, false
end
local function trackDrop(d)
    if d.Name == "_drop" and d:IsA("BasePart") then R.drops[d] = tick() end
end
for _, d in ipairs(workspace:GetChildren()) do trackDrop(d) end
R.conns.dropAdd = workspace.ChildAdded:Connect(trackDrop)
R.conns.dropRem = workspace.ChildRemoved:Connect(function(d)
    R.drops[d] = nil
    R.dropTried[d] = nil
end)
local function nextDrop(hrp, near, since)
    local mines = enemyMines()
    local best, bd
    for d, t in pairs(R.drops) do
        if not d.Parent then
            R.drops[d] = nil
        elseif tick() - t < 20 and not R.dropTried[d] and (#mines == 0 or safeAt(d.Position, mines)) then
            local ok
            if near then
                ok = t >= since - 0.5 and (d.Position - near).Magnitude < 25
            else
                ok = (d.Position - hrp.Position).Magnitude < R.LootRange
            end
            local dist = (d.Position - hrp.Position).Magnitude
            if ok and (not bd or dist < bd) then best, bd = d, dist end
        end
    end
    return best
end
R.conns.place = RunService.Stepped:Connect(function()
    local phase = matchPhase()
    if phase ~= R.phase then
        if R.On then log(("PHASE %s -> %s"):format(tostring(R.phase), phase)) end
        if phase == "Live" and R.phase ~= "Paused" then R.liveAt = tick() end
        if R.phase == "Live" and R.target then
            setTarget(nil)
            releaseCamera()
        end
        if phase ~= "Live" and phase ~= "Paused" then R.wasOn, R.startCF = false, nil end
        R.phase = phase
    end
    if not R.On then
        R.state = "Off"
        if R.wasOn then stopRage() end
        return
    end
    local _, hrp = myParts()
    if not hrp then R.target, R.state = nil, "Dead" return end
    if phase ~= "Live" then
        R.target, R.state = nil, phase
        return
    end
    if tick() - (R.liveAt or 0) < R.StartDelay then
        R.state = "Round starting"
        return
    end
    if not R.wasOn then
        R.wasOn, R.startCF = true, hrp.CFrame
        log("START")
    end
    local m = R.target
    if R.Counter then
        local cl = R.counterLock
        if cl and (not aliveModel(cl) or tick() - R.counterAt > 2 and not (cl:FindFirstChild("HumanoidRootPart") and (cl.HumanoidRootPart.Position - hrp.Position).Magnitude < 6)) then
            R.counterLock, cl = nil, nil
        end
        local threat
        for _, plr in ipairs(Players:GetPlayers()) do
            local c = plr ~= player and plr.Character or nil
            local r2 = c and c:FindFirstChild("HumanoidRootPart")
            if r2 and c ~= cl and not R.ignore[plr.Name] and aliveModel(c) and (r2.Position - hrp.Position).Magnitude < R.CounterRange and isEnemy(c, plr) then
                threat = c
                break
            end
        end
        if threat then
            log(("COUNTER %s"):format(threat.Name))
            R.counterLock, R.counterAt = threat, tick()
            R.lootDrop, R.lootPos = nil, nil
            if m ~= threat then setTarget(threat) end
            m = threat
        elseif cl and m ~= cl then
            setTarget(cl)
            m = cl
        end
    end
    if m then
        local hum = humOf(m)
        if not hum or hum.Health <= 0 or not m:IsDescendantOf(workspace) then
            if R.firedAt and tick() - R.lastShot < 2 then
                R.kills = R.kills + 1
                R.fails[m] = nil
                R.lootPos, R.lootKillAt, R.lootGot = R.lastTargetPos, tick(), 0
                log(("KILL %s (#%d)"):format(m.Name, R.kills))
            else
                log(("GONE %s"):format(m.Name))
            end
            setTarget(nil)
            m = nil
        else
            if R.lastHP and hum.Health < R.lastHP - 0.5 then
                R.hits = R.hits + 1
                R.lastDmgAt = tick()
                log(("HIT %s -%.0f (hp %.0f)"):format(m.Name, R.lastHP - hum.Health, hum.Health))
            end
            R.lastHP = hum.Health
            local since = R.firedAt and (tick() - math.max(R.firedAt, R.lastDmgAt)) or 0
            if R.nextReq then
                R.nextReq = false
                R.skip[m] = tick() + 3
                log(("SKIP %s (next key)"):format(m.Name))
                setTarget(nil)
                m = nil
            elseif since > R.Timeout then
                R.skip[m] = tick() + 3
                R.fails[m] = (R.fails[m] or 0) + 1
                log(("SKIP %s (shots not landing %.1fs)"):format(m.Name, since))
                setTarget(nil)
                m = nil
            elseif R.KatanaMode == "Skip" and deflecting(m) then
                R.skip[m] = tick() + 1.5
                log(("SKIP %s (katana block)"):format(m.Name))
                setTarget(nil)
                m = nil
            elseif R.SkipFF and m ~= R.counterLock and invincible(m) then
                R.skip[m] = tick() + 0.3
                log(("WAIT %s (forcefield)"):format(m.Name))
                setTarget(nil)
                m = nil
            end
        end
    end
    if R.Loot then
        local hum = humOf(player.Character)
        local low = hum and hum.Health < hum.MaxHealth * 0.6
        local d = R.lootDrop
        if d and (not d.Parent or tick() - R.lootAt > R.LootDwell) then
            local n = 0
            for o in pairs(R.drops) do
                if o == d or (o.Parent and d.Parent and (o.Position - d.Position).Magnitude < 3) then
                    R.dropTried[o] = true
                    n = n + 1
                end
            end
            R.dropTried[d] = true
            if R.lootPos then R.lootGot = R.lootGot + math.max(n, 1) end
            R.lootDrop, d = nil, nil
        end
        local pending = R.lootPos ~= nil and tick() - R.lootKillAt < 1.5 and R.lootGot < 2
        if not pending then R.lootPos = nil end
        if not d and (pending or low) then
            d = nextDrop(hrp, pending and R.lootPos or nil, R.lootKillAt)
            if d then
                R.lootDrop, R.lootAt, R.lootTouchAt = d, tick(), 0
                log(("LOOT going to drop %.0f studs away%s"):format((d.Position - hrp.Position).Magnitude, low and " (low hp)" or ""))
                if m then setTarget(nil) m = nil end
            end
        end
        if d then
            hold(hrp, CFrame.new(d.Position) * hrp.CFrame.Rotation)
            if firetouchinterest and tick() - (R.lootTouchAt or 0) > 0.05 then
                R.lootTouchAt = tick()
                pcall(firetouchinterest, hrp, d, 0)
                pcall(firetouchinterest, hrp, d, 1)
            end
            R.state = "Grabbing drop"
            return
        end
        if pending and R.lootGot == 0 and tick() - R.lootKillAt < 0.3 then
            hold(hrp, CFrame.new(R.lootPos + Vector3.new(0, 1, 0)) * hrp.CFrame.Rotation)
            R.state = "Waiting for drops"
            return
        end
    end
    if not m and tick() >= (R.pickAt or 0) then
        R.pickAt = tick() + 0.05
        m = pick(hrp.Position)
        if m then setTarget(m) end
    end
    if m then
        R.state = "Hunting"
        local troot = m:FindFirstChild("HumanoidRootPart")
        if troot then R.lastTargetPos = troot.Position end
        local cf, why = placeCF(m, enemyMines(), hrp)
        if cf then
            hold(hrp, cf)
        elseif why then
            R.skip[m] = tick() + 2
            R.fails[m] = (R.fails[m] or 0) + 1
            log(("SKIP %s (%s)"):format(m.Name, why == "mine" and "mined in" or "no safe spot"))
            setTarget(nil)
            R.state = why == "mine" and "Avoiding mines" or "No safe spot"
        end
    else
        R.state = "No targets"
        local standby
        if tick() - (R.liveAt or 0) < 3 then
            local bd
            for _, pl in ipairs(Players:GetPlayers()) do
                local c = pl ~= player and pl.Character or nil
                local r2 = c and c:FindFirstChild("HumanoidRootPart")
                if r2 and not R.ignore[pl.Name] and aliveModel(c) and isEnemy(c, pl) then
                    local d = (r2.Position - hrp.Position).Magnitude
                    if not bd or d < bd then standby, bd = c, d end
                end
            end
        end
        if standby then
            local sd, su = R.BehindDist or 1.1, 0
            if R.MeleeStandoff ~= false then
                pcall(function()
                    local info = fighterOf(standby).EquippedItem.Info
                    if info.Class == "Melee" or info.Type == "Melee" then sd, su = math.max(tonumber(info.AttackReach) or 6, tonumber(info.HeavyAttackReach) or 0) + 3, 1.5 end
                end)
            end
            hold(hrp, (standby:FindFirstChild("UpperTorso") or standby:FindFirstChild("Torso") or standby.HumanoidRootPart).CFrame * CFrame.new(0, su, sd))
            R.state = "Waiting on " .. standby.Name
        elseif R.Hide then
            hold(hrp, parkCF())
        end
    end
end)
