local function patch(tbl, key, wrap)
    if type(tbl) ~= "table" or type(tbl[key]) ~= "function" then return end
    local orig = tbl[key]
    tbl[key] = wrap(orig)
    P.restore[#P.restore + 1] = function() if tbl[key] ~= orig then tbl[key] = orig end end
end
patch(MC, "_GetWalkSpeed", function(orig)
    return function(self, ...)
        local v = orig(self, ...)
        if P.Speed ~= 1 and type(v) == "number" then return v * P.Speed end
        return v
    end
end)
patch(Airborne, "FromServer", function(orig)
    return function(self, ...)
        if P.NoKnockback then return end
        return orig(self, ...)
    end
end)
patch(Boosts, "SetBoost", function(orig)
    return function(self, kind, name, duration, amount, ...)
        if P.NoSlow and kind == "Speed" and type(amount) == "number" and amount < 0 then return end
        return orig(self, kind, name, duration, amount, ...)
    end
end)
if type(Vortexes) == "table" and type(Vortexes.UpdateForces) == "function" then
    local orig = Vortexes.UpdateForces
    rawset(Vortexes, "UpdateForces", function(self, ...)
        if P.NoVortex then
            for k, f in pairs(self._forces or {}) do pcall(function() self:_Cleanup(f) end) self._forces[k] = nil end
            if self._was_sitting then
                self._was_sitting = false
                pcall(function() FC.LocalFighter.Entity.Humanoid.Sit = false end)
            end
            return
        end
        return orig(self, ...)
    end)
    P.restore[#P.restore + 1] = function() pcall(rawset, Vortexes, "UpdateForces", nil) end
end
local baseJump = CONST and CONST.BASE_JUMPPOWER
local baseGravity = CONST and CONST.BASE_GRAVITY
local function applyConstants()
    if not CONST then return end
    if baseJump then CONST.BASE_JUMPPOWER = baseJump * P.Jump end
    if baseGravity then CONST.BASE_GRAVITY = baseGravity * (P.LowGravity and 0.55 or 1) end
    pcall(function() FC.LocalFighter.Entity.Humanoid.JumpPower = CONST.BASE_JUMPPOWER end)
end
P.restore[#P.restore + 1] = function()
    if CONST then
        if baseJump then CONST.BASE_JUMPPOWER = baseJump end
        if baseGravity then CONST.BASE_GRAVITY = baseGravity end
        pcall(function() FC.LocalFighter.Entity.Humanoid.JumpPower = baseJump end)
    end
end
