local function currentSkin()
    local v = Options.SkinDropdown and Options.SkinDropdown.Value
    if v and v ~= "" and (v == selectedWeapon or (CL.Cosmetics[v] and CL.Cosmetics[v].ItemName == selectedWeapon)) then return v end
    return selectedWeapon
