local function showPreview(skin, wrap, charm)
    if not SVM then pvLabel.Text = L["Preview not available"] return end
    skin = skin or currentSkin()
    wrap = wrap or (Options.WrapDropdown and Options.WrapDropdown.Value)
    charm = charm or (Options.CharmDropdown and Options.CharmDropdown.Value)
    GCall(function()
        if preview.key ~= skin then
            if preview.model then pcall(function() preview.model:Destroy() end) end
            preview.model, preview.key = nil, nil
            local ok, m = pcall(SVM.new, skin)
            if not ok then ok, m = pcall(SVM.new, selectedWeapon) end
            if ok and m then
                preview.model, preview.key = m, skin
                pcall(function()
                    local _, size = m.Model:GetBoundingBox()
                    local big = math.max(size.X, size.Y, size.Z)
                    if big > 0 then m:ScaleTo(m.Model:GetScale() * (2.6 / big)) end
                end)
            end
        end
        local m = preview.model
        if not m then return end
        preview.wrap, preview.charm = wrap, charm
        pcall(function() m:SetWrap({ Name = (wrap and wrap ~= "None") and wrap or nil }) end)
        pcall(function() m:SetCharm((charm and charm ~= "None") and { Name = charm } or nil) end)
    end)
    if preview.model then GCall(function() preview.model:SetParent(pvWorld) end) end
    local bits = { skin == selectedWeapon and selectedWeapon or skin }
    if wrap and wrap ~= "None" then bits[#bits + 1] = wrap end
    if charm and charm ~= "None" then bits[#bits + 1] = charm end
    pvLabel.Text = table.concat(bits, "  ·  ")
end
