local function weaponNames()
    local list = {}
    for _, n in ipairs((Options.WeaponDropdown and Options.WeaponDropdown.Values) or {}) do list[#list + 1] = n end
    return list
end
local function skinsFor(weapon)
    local list = { weapon }
    for name, info in pairs(CL.Cosmetics) do
        if type(info) == "table" and info.Type == "Skin" and info.ItemName == weapon and not info.Hidden then list[#list + 1] = name end
    end
    table.sort(list, function(a, b)
        if a == weapon then return true elseif b == weapon then return false end
        local ra, rb = CL.Cosmetics[a], CL.Cosmetics[b]
        local va = ra and CL.Rarities[ra.Rarity] and CL.Rarities[ra.Rarity].Value or 0
        local vb = rb and CL.Rarities[rb.Rarity] and CL.Rarities[rb.Rarity].Value or 0
        if va ~= vb then return va > vb end
        return a < b
    end)
    return list
end
local function listOfType(kind)
    local list = { "None" }
    for name, info in pairs(CL.Cosmetics) do
        if type(info) == "table" and info.Type == kind and not info.Hidden then list[#list + 1] = name end
    end
    table.sort(list, function(a, b) if a == "None" then return true elseif b == "None" then return false end return a < b end)
    return list
end
local function selectedValue()
    if current == "Skins" then return Options.SkinDropdown and Options.SkinDropdown.Value end
    if current == "Charms" then return Options.CharmDropdown and Options.CharmDropdown.Value end
    return Options.WrapDropdown and Options.WrapDropdown.Value
end
