        end)
        b.MouseLeave:Connect(function()
            if G.hoverTile == b then
                G.hoverTile = nil
                task.delay(0.2, function() if not G.hoverTile and gui.Enabled then showPreview() end end)
            end
        end)
    end
    b.Activated:Connect(function()
        if current == "Skins" then showPreview(name, nil, nil)
        elseif current == "Wraps" then showPreview(nil, name, nil)
        else showPreview(nil, nil, name) end
        pcall(function()
            if current == "Skins" then
                if Options.WeaponDropdown.Value ~= selectedWeapon then Options.WeaponDropdown:SetValue(selectedWeapon) end
                Options.SkinDropdown:SetValue(name)
            elseif current == "Charms" then
                if Options.WeaponDropdown.Value ~= selectedWeapon then Options.WeaponDropdown:SetValue(selectedWeapon) end
                Options.CharmDropdown:SetValue(name)
            else
                if Options.WeaponDropdown.Value ~= selectedWeapon then Options.WeaponDropdown:SetValue(selectedWeapon) end
                Options.WrapDropdown:SetValue(name)
            end
        end)
        task.defer(refreshGrid)
    end)
    tiles[#tiles + 1] = b
end
refreshGrid = function()
    clearGrid()
    local q = search.Text:lower()
    local list = current == "Skins" and skinsFor(selectedWeapon) or listOfType(current == "Charms" and "Charm" or "Wrap")
    local n = 0
    for _, name in ipairs(list) do
        if q == "" or name:lower():find(q, 1, true) then
            n = n + 1
            tile(name, n)
            if n >= 160 then break end
        end
    end
end
local weaponButtons = {}
local function refreshWeapons()
    for _, b in ipairs(weaponButtons) do b:Destroy() end
    weaponButtons = {}
    for i, name in ipairs(weaponNames()) do
        local b = Instance.new("TextButton")
        b.Size, b.BackgroundColor3, b.AutoButtonColor, b.Text, b.LayoutOrder = UDim2.new(1, 0, 0, 40), name == selectedWeapon and Color3.fromRGB(46, 38, 20) or INK, false, "", i
        b.Parent = weaponList
        corner(b, 6)
        if name == selectedWeapon then stroke(b, 1.4, true) end
        local img = Instance.new("ImageLabel")
        img.BackgroundTransparency, img.ScaleType, img.Position, img.Size = 1, Enum.ScaleType.Fit, UDim2.fromOffset(4, 4), UDim2.fromOffset(52, 32)
        img.Image = imageFor(name, name)
        img.Parent = b
        local t = text(b, name, 12, Color3.fromRGB(235, 228, 210), Enum.Font.GothamMedium)
        t.Position, t.Size, t.TextXAlignment, t.TextTruncate = UDim2.fromOffset(60, 0), UDim2.new(1, -64, 1, 0), Enum.TextXAlignment.Left, Enum.TextTruncate.AtEnd
        b.Activated:Connect(function()
            selectedWeapon = name
            pcall(function() Options.WeaponDropdown:SetValue(name) end)
            refreshWeapons()
            refreshGrid()
            showPreview()
        end)
        weaponButtons[#weaponButtons + 1] = b
    end
end
local function setTab(name)
    current = name
    for n, t in pairs(tabButtons) do
        local on = n == name
        t.b.BackgroundColor3 = on and Color3.fromRGB(46, 38, 20) or PANEL
        t.b.TextColor3 = on and GOLD or Color3.fromRGB(200, 190, 170)
        t.s.Color = on and GOLD or Color3.fromRGB(60, 54, 42)
    end
    refreshGrid()
end
for name, t in pairs(tabButtons) do t.b.Activated:Connect(function() setTab(name) end) end
search:GetPropertyChangedSignal("Text"):Connect(function()
    if G.searchAt then return end
    G.searchAt = true
    task.delay(0.25, function() G.searchAt = nil refreshGrid() end)
end)
local dragging
header.InputBegan:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
        dragging = { input = i, start = i.Position, pos = win.Position }
    end
end)
G.conns.move = UIS.InputChanged:Connect(function(i)
    if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or (i.UserInputType == Enum.UserInputType.Touch and i == dragging.input)) then
        local d = i.Position - dragging.start
        win.Position = UDim2.new(dragging.pos.X.Scale, dragging.pos.X.Offset + d.X, dragging.pos.Y.Scale, dragging.pos.Y.Offset + d.Y)
    end
end)
G.conns.up = UIS.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = nil end
end)
G.conns.spin = RunService.RenderStepped:Connect(function()
    if not gui.Enabled then return end
    local rot = (os.clock() * 110) % 360
    for _, g in ipairs(G.spin) do g.Rotation = rot end
end)
function H.OpenGallery()
    rescale()
    selectedWeapon = (Options.WeaponDropdown and Options.WeaponDropdown.Value) or selectedWeapon
    gui.Enabled = true
    refreshWeapons()
    setTab(current)
    preview.wrap = Options.WrapDropdown and Options.WrapDropdown.Value
    preview.charm = Options.CharmDropdown and Options.CharmDropdown.Value
    showPreview()
end
local GalleryBox = H.Tabs.Cosmetics:AddLeftGroupbox(L["Gallery"], "image")
GalleryBox:AddLabel(L["Browse every skin, charm and wrap with pictures."], true)
GalleryBox:AddButton({ Text = L["Open gallery"], Func = function() H.OpenGallery() end })
function H.GalleryUnload()
    for _, c in pairs(G.conns) do pcall(function() c:Disconnect() end) end
    if preview and preview.model then GCall(function() preview.model:Destroy() end) end
    pcall(function() gui:Destroy() end)
    H.GalleryUnload = nil
end
H.Unloaders = H.Unloaders or {}
H.Unloaders.gallery = H.GalleryUnload
end)
pcall(function()
    local Library = _G.__ObsidianLib
    if not Library then return end
    pcall(function()
        if _G.RivalsHub and _G.RivalsHub.SaveManager then
            _G.RivalsHub.SaveManager:LoadAutoloadConfig()
        end
    end)
    pcall(function()
        local SM = _G.RivalsHub and _G.RivalsHub.SaveManager
        if not SM then return end
        local folder = SM.Folder or "rivals/weapon-customizer"
        local name
        pcall(function()
            local f = folder .. "/settings/autoload.txt"
            if isfile(f) then name = readfile(f) end
        end)
        if not name or name == "" then
            name = "auto"
            pcall(function() SM:Save(name) end)
            pcall(function() SM:SaveAutoloadConfig(name) end)
        end
        local ready, pending = false, false
        task.delay(4, function() ready = true end)
        local function schedule()
            if not ready or pending then return end
            pending = true
            task.delay(2, function()
                pending = false
                pcall(function() SM:Save(name) end)
            end)
        end
        local function wrap(obj)
            if type(obj) ~= "table" or obj.__autosave then return end
            obj.__autosave = true
            local key = (obj.Type == "KeyPicker") and "ChangedCallback" or "Callback"
            local cb = obj[key]
            obj[key] = function(...)
                if cb then cb(...) end
                schedule()
            end
        end
        for _, t in pairs(Library.Toggles or {}) do pcall(wrap, t) end
        for _, o in pairs(Library.Options or {}) do pcall(wrap, o) end
        _G.RivalsHub.AutoSaveName = name
    end)
    pcall(function()
        if Library.Toggle and not Library.Toggled then
            Library:Toggle(true)
        end
    end)
end)

end
